ServerEvents.tags('item', event => {
  // fixes for recipes that ask for tags no mod provides under that name
  event.add('c:egg', '#c:eggs')                                  // Ender IO dye alloys
  event.add('c:leather', '#c:leathers')                          // Blood Magic soul forge (reagent of holding)
  event.add('c:ices/ice', 'minecraft:ice')                       // Ender IO vat (cloud seed)
  event.add('minecraft:convertable_to_mud', ['minecraft:dirt', 'minecraft:coarse_dirt', 'minecraft:rooted_dirt'])   // Create mud mixing
  // Extra Utilities Reborn spikes/drums/trash cans have no recipe (xu2blocks ships the SF3 versions and disables these): hide them in JEI/EMI
  event.add('c:hidden_from_recipe_viewers', ["euru:wooden_spike", "euru:stone_spike", "euru:iron_spike", "euru:gold_spike", "euru:diamond_spike", "euru:netherite_spike", "euru:trash_can", "euru:trash_chest", "euru:stone_drum", "euru:iron_drum", "euru:reinforced_large_drum"])
  // Mystical Agriculture tier storage-block tags held the essence block, not the ingot block
  event.remove('c:storage_blocks/inferium', 'mysticalagriculture:inferium_block')
  event.add('c:storage_blocks/inferium', 'mysticalagriculture:inferium_ingot_block')
  event.remove('c:storage_blocks/prudentium', 'mysticalagriculture:prudentium_block')
  event.add('c:storage_blocks/prudentium', 'mysticalagriculture:prudentium_ingot_block')
  event.remove('c:storage_blocks/intermedium', 'mysticalagriculture:intermedium_block')
  event.add('c:storage_blocks/intermedium', 'mysticalagriculture:intermedium_ingot_block')
  event.remove('c:storage_blocks/superium', 'mysticalagriculture:superium_block')
  event.add('c:storage_blocks/superium', 'mysticalagriculture:superium_ingot_block')
  event.remove('c:storage_blocks/supremium', 'mysticalagriculture:supremium_block')
  event.add('c:storage_blocks/supremium', 'mysticalagriculture:supremium_ingot_block')
})

